    public static String family(String id) {
        return id.replaceAll("\\d+(mb|gb)?", "");
    }

    public static boolean lists(String page, String path, boolean byFamily) {
        String fam = family(path);
        for (var m : List.of(RECIPE_ITEMS, MORE_ITEMS)) {
            List<String> ids = m.get(page);
            if (ids != null) for (String id : ids) if (byFamily ? family(id).equals(fam) : id.equals(path)) return true;
        }
        return false;
    }

    @Nullable
    public static String page(String path) {
        for (var nd : AchievementTree.NODES)
            if (AchievementTree.proofItems(nd).contains(path)) return nd.page();
        for (boolean fam : new boolean[] {false, true})
            for (var m : List.of(RECIPE_ITEMS, MORE_ITEMS))
                for (String pg : m.keySet()) if (lists(pg, path, fam)) return pg;
        return null;
    }
